import { Effect, Layer } from "effect"
import { InventoryRepository } from "./InventoryRepository.js"
import { InventorySummary } from "./InventorySummary.js"

const loadSummary = Effect.gen(function*() {
    const repository = yield* InventoryRepository
    const items = yield* repository.listActive()
    const lowStock = items
      .filter((item) => item.quantity < item.reorderPoint)
      .map((item) => ({
        sku: item.sku,
        missing: item.reorderPoint - item.quantity
      }))

    return {
      activeSkus: items.length,
      totalUnits: items.reduce((total, item) => total + item.quantity, 0),
      lowStock
    }
  })

export const InventorySummaryLive = Layer.effect(
  InventorySummary,
  Effect.gen(function*() {
    const repository = yield* InventoryRepository
    const summary = loadSummary.pipe(
      Effect.provideService(InventoryRepository, repository)
    )

    return InventorySummary.of({
      refresh: () => summary
    })
  })
)
